local a="/eh2_hw_config.tbl"if not fs.exists(a)then print("No "..a.." found -- run /calibrate first; there's nothing to patch.")return end;local b=fs.open(a,"r")local c=textutils.unserialise(b.readAll()or"")b.close()if type(c)~="table"then print("Config file unreadable; aborting (no change made).")return end;c.bindings=c.bindings or{}local d,e=c.bindings.signHeading,c.bindings.signYawRate;c.bindings.signHeading=-1;c.bindings.signYawRate=1;local f=fs.open(a,"w")f.write(textutils.serialise(c))f.close()print(("signHeading: %s -> -1"):format(tostring(d)))print(("signYawRate: %s -> 1  (reverting the earlier wrong flip)"):format(tostring(e)))print("Saved. Now launch:  hovertest")